SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;

-- Grants: the API reads and creates scenarios and never changes or deletes
-- one; the worker only reads them (0002); nobody calls the guard.
SELECT pg_temp.check(has_table_privilege('twin_api','twin.scenarios','SELECT') AND has_table_privilege('twin_api','twin.scenarios','INSERT'),
  'the API reads and creates scenarios');
SELECT pg_temp.check(NOT has_table_privilege('twin_api','twin.scenarios','UPDATE') AND NOT has_table_privilege('twin_api','twin.scenarios','DELETE')
    AND NOT has_table_privilege('twin_api','twin.scenarios','TRUNCATE'), 'the API never changes or deletes a scenario');
SELECT pg_temp.check(has_table_privilege('twin_worker','twin.scenarios','SELECT') AND NOT has_table_privilege('twin_worker','twin.scenarios','INSERT')
    AND NOT has_table_privilege('twin_worker','twin.scenarios','UPDATE') AND NOT has_table_privilege('twin_worker','twin.scenarios','DELETE'),
  'the worker only reads scenarios');
SELECT pg_temp.check(NOT has_function_privilege('public','twin.protect_scenario_creation()','EXECUTE'), 'PUBLIC cannot call the creation guard');
SELECT pg_temp.check(EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname='twin' AND p.proname='protect_scenario_creation' AND p.proconfig @> ARRAY['search_path=pg_catalog, pg_temp']),
  'the creation guard fixes its search_path');
SELECT pg_temp.check(relforcerowsecurity AND relrowsecurity, 'scenarios force RLS') FROM pg_class WHERE oid='twin.scenarios'::regclass;
SELECT pg_temp.check(EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname='twin' AND tablename='scenarios' AND indexname='scenarios_base_idx'
    AND indexdef LIKE '%(organization_id, base_version_id, created_at, id)%'), 'the list has its index');

SET LOCAL ROLE twin_api;
-- A person's scenario on the latest version and one on the older version
-- (D-067: any version), for the scoped user, at the transaction's time.
SELECT pg_temp.scenario('scn_01M4YDQK00TA00000000000004', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000002', 'Eight CI runners', 'usr_01M4YDQK00TA00000000000001') \gexec
SELECT pg_temp.scenario('scn_01M4YDQK00TA00000000000005', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000001', repeat('é', 200), 'usr_01M4YDQK00TA00000000000001') \gexec
SET CONSTRAINTS ALL IMMEDIATE; -- a scenario without a source proposal needs none at commit (0013)
SET CONSTRAINTS ALL DEFERRED;
SELECT pg_temp.check(count(*) = 2 AND bool_and(created_at = now() AND source_proposal_id IS NULL AND created_by = 'usr_01M4YDQK00TA00000000000001'),
  'the two scenarios are the scoped user''s, now, without a source proposal')
  FROM twin.scenarios WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id IN ('scn_01M4YDQK00TA00000000000004','scn_01M4YDQK00TA00000000000005');

-- D-080 (b): the API creates a scenario for the scoped user only, and at
-- the time of its transaction.
SELECT pg_temp.must_fail(pg_temp.scenario('scn_01M4YDQK00TA00000000000006', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000002', 'For someone else', 'usr_01M4YDQK00TA00000000000002'), '42501');
SELECT pg_temp.must_fail($q$INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,created_by,created_at)
    VALUES ('scn_01M4YDQK00TA00000000000006','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000002','Back-dated','[]','sha256:4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945','usr_01M4YDQK00TA00000000000001',now() - interval '1 day')$q$, '55000');
SELECT pg_temp.must_fail($q$INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,created_by,created_at)
    VALUES ('scn_01M4YDQK00TA00000000000006','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000002','Ahead','[]','sha256:4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945','usr_01M4YDQK00TA00000000000001',now() + interval '1 second')$q$, '55000');
-- D-080 (a): a name is 1 to 200 characters.
SELECT pg_temp.must_fail(pg_temp.scenario('scn_01M4YDQK00TA00000000000006', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000002', n, 'usr_01M4YDQK00TA00000000000001'), '23514')
  FROM unnest(ARRAY['', repeat('x', 201)]) AS n;
-- 0001: the base is a version of the same organization and model; the
-- patch is an array; the organization is the transaction's (RLS).
SELECT pg_temp.must_fail(pg_temp.scenario('scn_01M4YDQK00TA00000000000006', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000022', 'Another model''s version', 'usr_01M4YDQK00TA00000000000001'), '23503');
SELECT pg_temp.must_fail(pg_temp.scenario('scn_01M4YDQK00TA00000000000006', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TB00000000000001', 'Another tenant''s version', 'usr_01M4YDQK00TA00000000000001'), '23503');
SELECT pg_temp.must_fail(pg_temp.scenario('scn_01M4YDQK00TA00000000000006', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000021', 'No such version', 'usr_01M4YDQK00TA00000000000001'), '23503');
SELECT pg_temp.must_fail($q$INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,created_by)
    VALUES ('scn_01M4YDQK00TA00000000000006','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000002','Not a patch','{"op":"test"}','sha256:4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945','usr_01M4YDQK00TA00000000000001')$q$, '23514');
SELECT pg_temp.must_fail($q$INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,created_by)
    VALUES ('scn_01M4YDQK00TA00000000000006','org_01M4YDQK00TB00000000000000','mdl_01M4YDQK00TB00000000000001','mv_01M4YDQK00TB00000000000001','Into tenant B','[]','sha256:4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945','usr_01M4YDQK00TA00000000000001')$q$, '42501');
SELECT pg_temp.must_fail($q$INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,created_by)
    VALUES ('scn_01M4YDQK00TA00000000000006','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000002','Bad hash','[]','sha256:x','usr_01M4YDQK00TA00000000000001')$q$, '23514');

-- TEST-004: nobody changes or deletes a scenario; the API has no privilege
-- to, and the schema owner is refused by 0001's trigger.
SELECT pg_temp.must_fail(format('UPDATE twin.scenarios SET %s WHERE organization_id=%L AND id=%L', s, 'org_01M4YDQK00TA00000000000000', 'scn_01M4YDQK00TA00000000000004'), '42501')
  FROM unnest(ARRAY[$q$name='Renamed'$q$, $q$patch='[{"op":"test","path":"/name","value":"x"}]'$q$, $q$base_version_id='mv_01M4YDQK00TA00000000000001'$q$]) AS s;
SELECT pg_temp.must_fail(format('DELETE FROM twin.scenarios WHERE organization_id=%L AND id=%L', 'org_01M4YDQK00TA00000000000000', 'scn_01M4YDQK00TA00000000000004'), '42501');
SELECT pg_temp.must_fail('TRUNCATE twin.scenarios', '42501');
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(format('UPDATE twin.scenarios SET %s WHERE organization_id=%L AND id=%L', s, 'org_01M4YDQK00TA00000000000000', 'scn_01M4YDQK00TA00000000000004'), '55000')
  FROM unnest(ARRAY[$q$name='Renamed'$q$, $q$patch_hash='sha256:1111111111111111111111111111111111111111111111111111111111111111'$q$, $q$created_by='usr_01M4YDQK00TA00000000000002'$q$]) AS s;
SELECT pg_temp.must_fail(format('DELETE FROM twin.scenarios WHERE organization_id=%L AND id=%L', 'org_01M4YDQK00TA00000000000000', 'scn_01M4YDQK00TA00000000000004'), '55000');
-- CASCADE: proposals and runs reference scenarios, and without it the
-- foreign keys would refuse before the trigger (constraints.sql does the
-- same for versions).
SELECT pg_temp.must_fail('TRUNCATE twin.scenarios CASCADE', '55000');
-- The schema owner is not held to the creator and the time (operators).
INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,created_by,created_at)
  VALUES ('scn_01M4YDQK00TA00000000000007','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000002','Restored','[]','sha256:4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945','usr_01M4YDQK00TA00000000000002',now() - interval '1 day');
SELECT pg_temp.check(name = 'Eight CI runners' AND patch = '[]'::jsonb, 'the scenario is as it was created')
  FROM twin.scenarios WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='scn_01M4YDQK00TA00000000000004';

-- TEST-010: a transaction sees only its own organization's scenarios,
-- and none without one; the API cannot read tenant B's from tenant A.
SET LOCAL ROLE twin_api;
SELECT pg_temp.check(count(*) = 3, 'tenant A sees its three scenarios') FROM twin.scenarios;
SELECT pg_temp.check(count(*) = 0, 'tenant A does not see tenant B''s scenario') FROM twin.scenarios WHERE id='scn_01M4YDQK00TB00000000000001';
SELECT set_config('app.organization_id','org_01M4YDQK00TB00000000000000',true), set_config('app.user_id','usr_01M4YDQK00TB00000000000001',true);
SELECT pg_temp.check(count(*) = 1 AND bool_and(id = 'scn_01M4YDQK00TB00000000000001'), 'tenant B sees only its own') FROM twin.scenarios;
SELECT set_config('app.organization_id','',true), set_config('app.user_id','',true);
SELECT pg_temp.check(count(*) = 0, 'no organization, no scenario') FROM twin.scenarios;
SET LOCAL ROLE twin_worker;
SELECT set_config('app.organization_id','org_01M4YDQK00TA00000000000000',true);
SELECT pg_temp.check(count(*) = 3, 'the worker reads the organization''s scenarios') FROM twin.scenarios;
SELECT pg_temp.must_fail(pg_temp.scenario('scn_01M4YDQK00TA00000000000008', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000002', 'By the worker', 'usr_01M4YDQK00TA00000000000001'), '42501');

-- The list reads a version's scenarios in (created_at, id) order: the
-- three on version 2, two of them created in this transaction, so the ID
-- breaks the tie.
SET LOCAL ROLE twin_api;
SELECT set_config('app.user_id','usr_01M4YDQK00TA00000000000001',true);
SELECT pg_temp.scenario('scn_01M4YDQK00TA00000000000009', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000002', 'Nine CI runners', 'usr_01M4YDQK00TA00000000000001') \gexec
SELECT pg_temp.check(array_agg(id::text ORDER BY created_at, id) = ARRAY['scn_01M4YDQK00TA00000000000007','scn_01M4YDQK00TA00000000000004','scn_01M4YDQK00TA00000000000009']::text[],
  'the version''s scenarios in (created_at, id) order')
  FROM twin.scenarios WHERE organization_id='org_01M4YDQK00TA00000000000000' AND base_version_id='mv_01M4YDQK00TA00000000000002';
ROLLBACK;
